import{_ as o,a,c as d,ac as n}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"MongoDB 数据库与认证操作","description":"MongoDB 数据库、集合、认证连接与建库操作。","frontmatter":{"title":"MongoDB 数据库与认证操作","description":"MongoDB 数据库、集合、认证连接与建库操作。","sources":[{"repository":"jekyall_blog","file":"_posts/DataStorage/mongodb/2019-03-01-mongodb-index.md","date":"Mon Sep 19 2022 12:21:48 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"mongodb","title":"MongoDB","link":"/topics/mongodb/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","summary":"MongoDB 数据库、集合、认证连接与建库操作。","status":"active","related":[{"title":"MongoDB 数据模型与配置","link":"/middleware/databases/mongodb/plus/subjects/mongodb-base-copy","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：版本化任务完整 CLI","link":"/middleware/databases/mongodb/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"MongoDB：连接诊断、备份恢复与自检","link":"/middleware/databases/mongodb/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：模型、索引、原子性与一致性","link":"/middleware/databases/mongodb/base/intermediate/mechanisms","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：文档、命名空间与连接","link":"/middleware/databases/mongodb/base/basic/start","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MongoDB 操作与命令","link":"/middleware/databases/mongodb/plus/ecosystem/mongodb-general-general"},"next":{"text":"MongoDB 数据模型与配置","link":"/middleware/databases/mongodb/plus/subjects/mongodb-base-copy"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MongoDB 操作与命令","link":"/middleware/databases/mongodb/plus/ecosystem/mongodb-general-general"},"next":{"text":"MongoDB 数据模型与配置","link":"/middleware/databases/mongodb/plus/subjects/mongodb-base-copy"}},"headers":[],"relativePath":"middleware/databases/mongodb/plus/subjects/mongodb-index.md","filePath":"middleware/databases/mongodb/plus/subjects/mongodb-index.md"}'),s={name:"middleware/databases/mongodb/plus/subjects/mongodb-index.md"};function t(l,e,i,r,c,g){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="mongodb-数据库与认证操作" tabindex="-1">MongoDB 数据库与认证操作 <a class="header-anchor" href="#mongodb-数据库与认证操作" aria-label="Permalink to &quot;MongoDB 数据库与认证操作&quot;">​</a></h1><p><span id="mongodb-database"></span></p><h2 id="mongo-database" tabindex="-1">Mongo Database <a class="header-anchor" href="#mongo-database" aria-label="Permalink to &quot;Mongo Database&quot;">​</a></h2><p>数据库（Database）在 MongoDB 中是一个顶级容器，用于组织和存储集合（Collections）。每个数据库可以包含多个集合，而每个集合又可以包含多个文档（Documents）。以下是 MongoDB 数据库的详解和一些操作注意事项：</p><h2 id="数据库的特点" tabindex="-1">数据库的特点 <a class="header-anchor" href="#数据库的特点" aria-label="Permalink to &quot;数据库的特点&quot;">​</a></h2><ol><li><p><strong>独立性</strong>：每个数据库是相互独立的，有自己的权限设置和存储空间。</p></li><li><p><strong>命名空间</strong>：数据库名是大小写敏感的，且不能包含以下字符：<code>/\\. &quot;$*&lt;&gt;:|?</code></p></li><li><p><strong>集合的分组</strong>：数据库可以通过集合来组织和存储数据，方便管理和查询。</p></li><li><p><strong>权限控制</strong>：MongoDB 支持对数据库进行权限控制，可以通过用户角色和权限来管理数据库访问。</p></li><li><p><strong>备份和恢复</strong>：MongoDB 提供了备份和恢复数据库的功能，方便进行数据的备份和恢复操作。</p></li></ol><h2 id="操作注意事项" tabindex="-1">操作注意事项 <a class="header-anchor" href="#操作注意事项" aria-label="Permalink to &quot;操作注意事项&quot;">​</a></h2><ol><li><p><strong>创建数据库</strong>：<code>use mydatabase</code> 只切换当前数据库上下文。数据库尚不存在时，首次写入数据或显式创建集合才会实际创建相应数据库和集合。参见<a href="https://www.mongodb.com/docs/manual/core/databases-and-collections/" target="_blank" rel="noopener noreferrer">官方数据库与集合说明</a>。</p></li><li><p><strong>切换数据库</strong>：使用 <code>use</code> 命令可以切换当前操作的数据库。例如，要切换到 <code>mydatabase</code>，可以执行 <code>use mydatabase</code>。</p></li><li><p><strong>查看当前数据库</strong>：可以使用 <code>db</code> 命令查看当前正在使用的数据库。例如，执行 <code>db</code> 命令会显示当前数据库的名称。</p></li><li><p><strong>查看所有数据库</strong>：可以使用 <code>show dbs</code> 命令来查看 MongoDB 中所有的数据库列表。</p></li><li><p><strong>删除数据库</strong>：可以使用 <code>db.dropDatabase()</code> 命令来删除当前数据库。请谨慎执行此操作，删除数据库会同时删除其中的所有集合和文档。</p></li><li><p><strong>备份和恢复</strong>：可以使用 <code>mongodump</code> 和 <code>mongorestore</code> 命令来进行 MongoDB 数据库的备份和恢复操作。</p></li><li><p><strong>权限管理</strong>：MongoDB 支持对数据库进行权限管理，可以使用 <code>db.createUser()</code> 命令创建用户并分配权限，以控制用户对数据库的访问。</p></li><li><p><strong>性能优化</strong>：在设计数据库时，应考虑到数据的结构和索引的设计，以及合理利用 MongoDB 提供的分片和复制等功能来优化性能。</p></li><li><p><strong>监控和管理</strong>：定期监控数据库的性能和运行状态，及时处理异常和优化配置，保证数据库的稳定运行。</p></li></ol><h2 id="连接数据库" tabindex="-1">连接数据库 <a class="header-anchor" href="#连接数据库" aria-label="Permalink to &quot;连接数据库&quot;">​</a></h2><p>原记录使用旧版 <code>mongo</code> shell；当前操作请使用与部署兼容的 <code>mongosh</code>。下面只解释连接参数，不代表已连接或验证某个环境。</p><ul><li>主机与端口：<code>DB_HOST</code>、<code>DB_PORT</code> 替换为目标实例地址。</li><li>用户：<code>DB_USER</code> 替换为有权限的账号。</li><li>认证库：<code>--authenticationDatabase admin</code> 指用户创建于 admin；数据读写所在的库可不同。应以实际账号创建位置为准。</li><li>密码：使用交互式提示输入，避免把密码写入文档或 shell 历史。</li></ul><p><code>mongosh --host DB_HOST --port DB_PORT --username DB_USER --authenticationDatabase admin --password</code></p><p>历史命令中的 <code>mongo</code> 与上述 <code>mongosh</code> 不应混当同一个客户端版本。连接成功后先用 <code>db</code> 和 <code>db.version()</code> 核对上下文及服务端版本。</p><h2 id="操作数据库" tabindex="-1">操作数据库 <a class="header-anchor" href="#操作数据库" aria-label="Permalink to &quot;操作数据库&quot;">​</a></h2><blockquote><p>创建的数据库 <code>mydatabase</code> 并不在数据库的列表中， 要显示它，我们需要向 <code>mydatabase</code> 数据库插入一些数据。</p></blockquote><ul><li>切换到 mydatabase 上下文（此时不保证已创建）：<code>use mydatabase</code></li><li>查看当前数据库：<code>db</code></li><li>查看所有数据库列表：<code>show dbs</code></li><li>向当前库的 mydatabase 集合首次写入（必要时创建库和集合）：<code>db.mydatabase.insertOne({&quot;name&quot;:&quot;Example User&quot;})</code></li><li>查看所有数据库列表：<code>show dbs</code></li><li>查询版本信息：<code>db.version()</code></li><li>实例的状态信息：<code>db.serverStatus()</code></li><li>实例的内存使用情况：<code>db.runCommand({ serverStatus: 1, mem: 1 })</code></li><li>实例的存储引擎信息：<code>db.runCommand({ engineStatus: 1 })</code></li><li>查看数据库状态：<code>db.stats()</code></li></ul>',16)])])}const p=o(s,[["render",t]]);export{m as __pageData,p as default};
